        }
        let changed: Vec<&RelPath> = a
            .files
            .iter()
            .filter(|(p, rec)| b.files.get(*p) != Some(rec))
            .map(|(p, _)| p)
            .chain(b.files.keys().filter(|p| !a.files.contains_key(*p)))
            .collect();
